        function activarComportamientoInputs() {
            const inputSelector = "[id^='passengerDetails-firstName'], [id^='passengerDetails-lastName'], [id^='documentInfo-documentNumber'], [id^='passengerInfo-emails'], [id^='passengerInfo-phones0-number'], [id^='preferences-frequentFlyer0-number']";

            $(inputSelector).each(function() {
                const $input = $(this);
                const inputId = $input.attr("id");
                const $label = $(`#${inputId}-label`);

                const $parentDiv = $input.closest("div.MuiInputBase-root");

                // Focus
                $input.on("focus", function() {
                    $label.addClass("MuiInputLabel-shrink Mui-focused");
                    $parentDiv.addClass("Mui-focused");
                    $parentDiv.find(".jss3").addClass("jss4");
                });

                // Blur
                $input.on("blur", function() {
                    if ($input.val()) {
                        $label.removeClass("Mui-focused");
                        $parentDiv.removeClass("Mui-focused");
                    } else {
                        $label.removeClass("MuiInputLabel-shrink Mui-focused");
                        $parentDiv.removeClass("Mui-focused");
                        $parentDiv.find(".jss3").removeClass("jss4");
                    }
                });

                // Si ya tiene valor cargado
                if ($input.val()) {
                    $label.addClass("MuiInputLabel-shrink");
                    $parentDiv.removeClass("Mui-focused");
                }
            });
        }

        // renderPassengers(JSON.parse(my_data['pasajeros']));
        renderPassengers({
            adultos: 1,
            ninos: 0,
            bebes: 0
        });
        activarComportamientoInputs();

        function validarTodosLosPasajeros() {
            let esValido = true;

            $(".passengerstyle__Ol-ejn4dv-0.egpEjI li form").each(function() {
                const $form = $(this);

                const nombre = $form.find("input[name='passengerDetails.firstName']").val().trim();
                const apellido = $form.find("input[name='passengerDetails.lastName']").val().trim();
                const numDoc = $form.find("input[name='documentInfo.documentNumber']").val().trim();
                const email = $form.find("input[name='passengerInfo.emails']").val().trim();
                const telefono = $form.find("input[name='passengerInfo.phones[0].number']").val().trim();
                const nacimiento = $form.find("input[id^='passengerInfo-dateOfBirth-']").val().trim();

                const $li = $form.closest("li");
                const $accordionSummary = $li.find(".xp-Accordion-summary");
                const wrapperClass = "wrapperSummary";

                let tipoPasajero = "Pasajero";
                const liClass = $li.attr("class") || "";

                if (liClass.includes("ADT")) tipoPasajero = "Adulto";
                else if (liClass.includes("CNN")) tipoPasajero = "Niño";
                else if (liClass.includes("INF")) tipoPasajero = "Bebé";

                const advertenciaHTML = `
            <div class="${wrapperClass}">
                <div>
                    <span class="emptyPassenger">${tipoPasajero}</span>
                    <span class="errorMessage">Completa y guarda los datos del pasajero.</span>
                </div>
                <div class="wrapperValidationIcon">
                    <i class="sc-fznKkj fqrfQf" aria-hidden="true" color="#B30F3B">
                        <svg xmlns="http://www.w3.org/2000/svg" width="20px" height="20px" viewBox="0 0 20 20" fill="none" focusable="false">
                            <path fill="currentColor" d="M10 .007C4.484.007.007 4.484.007 10S4.484 19.993 10 19.993s9.993-4.477 9.993-9.993S15.516.007 10 .007zm.999 15.992H9V14h1.999v1.999zm0-4H9.001V4h1.998v8z"></path>
                        </svg>
                    </i>
                </div>
            </div>`;

                console.log($accordionSummary.find(`.${wrapperClass}`).find(".wrapperValidationIcon").length);
                if (!nombre || !apellido || !numDoc || !email || !telefono || !nacimiento) {
                    esValido = false;

                    if ($accordionSummary.find(`.${wrapperClass}`).find(".wrapperValidationIcon").length === 0) {
                        $accordionSummary.find(`.${wrapperClass}`).remove();
                        $accordionSummary.append(advertenciaHTML);
                    }
                } else {
                    $accordionSummary.find(`.${wrapperClass}`).remove();
                }
            });

            return esValido;
        }


